import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Power Platform Well-Architected — enumerated source for the Power Platform Well-Architected assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/power-platform-well-architected-checklist.md","filePath":"frameworks/power-platform-well-architected-checklist.md"}'),n={name:"frameworks/power-platform-well-architected-checklist.md"};function i(d,e,s,l,c,m){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="power-platform-well-architected-—-enumerated-source-for-the-power-platform-well-architected-assessment" tabindex="-1">Power Platform Well-Architected — enumerated source for the Power Platform Well-Architected assessment <a class="header-anchor" href="#power-platform-well-architected-—-enumerated-source-for-the-power-platform-well-architected-assessment" aria-label="Permalink to &quot;Power Platform Well-Architected — enumerated source for the Power Platform Well-Architected assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>pp.wellarchitected.yaml</code> scores Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/689fd8d9-1000-4cbb-8096-a6c8f3294fc7/" target="_blank" rel="noreferrer">Power Platform Well-Architected</a> assessment, which examines the reliability, security, operational excellence, performance efficiency and user experience of a workload design. <code>src/assess/rules/pp.wellarchitected.yaml</code> is written against this page only, and every rule cites an item from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/689fd8d9-1000-4cbb-8096-a6c8f3294fc7/" target="_blank" rel="noreferrer">Power Platform Well-Architected</a> (60 minutes, multiple choice and multiple response; question text not published)</td></tr><tr><td>Framework version</td><td>Power Platform Well-Architected pillar checklists on Microsoft Learn, current (Reliability RE:01-08, Security SE:01-10, Operational Excellence OE:01-11, Performance Efficiency PE:01-10, Experience Optimization XO:01-10); no version number is published</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The assessment page, the pillars page and each of the five pillar checklist pages were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25, and every code and recommendation below was copied from those tables. Per-item guidance links are the checklist&#39;s own links. The individual guidance articles were not each read in full. Power Platform API names in the last section were checked against the Learn permission reference and REST reference overview.</td></tr></tbody></table><h2 id="the-questions-are-scout-derived" tabindex="-1">The questions are Scout-derived <a class="header-anchor" href="#the-questions-are-scout-derived" aria-label="Permalink to &quot;The questions are Scout-derived&quot;">​</a></h2><p><strong>This is not Microsoft&#39;s question list.</strong> Microsoft does not publish the assessment&#39;s questions. What it does publish is the pillar checklists, each recommendation carrying a code (RE:01, SE:01 and so on). Scout turns each checklist recommendation into one yes/no statement, so the <code>PPWAF-*</code> identifiers carry Microsoft&#39;s codes (<code>PPWAF-RE-01</code> is Microsoft&#39;s RE:01) but the wording of every question is Scout&#39;s paraphrase, and the assessment&#39;s own multiple-choice questions may split, merge or reorder them. A score from this file says how the workload sits against the published checklist. It is not the score Microsoft&#39;s assessment would return.</p><h2 id="scout-does-not-read-power-platform-data-yet" tabindex="-1">Scout does not read Power Platform data yet <a class="header-anchor" href="#scout-does-not-read-power-platform-data-yet" aria-label="Permalink to &quot;Scout does not read Power Platform data yet&quot;">​</a></h2><p>Scout collects Azure Resource Manager, Resource Graph and a small set of Microsoft Graph data. It does not call the Power Platform admin APIs, so it has no inventory of environments, data policies, apps or flows. All 49 items are therefore <strong>manual</strong>: each rule has <code>manual: true</code> and <code>query: null</code>, and the answer comes from the questionnaire (<a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>). Unanswered items show as Manual and are left out of the score; they are never counted as failures. Entra Conditional Access, which SE:05 touches, is read by Scout&#39;s Entra inventory but is not part of the assessment collection, so it cannot be used as evidence either.</p><p>Sources, the pillar checklists:</p><ul><li>[RE] <a href="https://learn.microsoft.com/power-platform/well-architected/reliability/checklist" target="_blank" rel="noreferrer">Recommendation checklist for Reliability</a></li><li>[SE] <a href="https://learn.microsoft.com/power-platform/well-architected/security/checklist" target="_blank" rel="noreferrer">Recommendation checklist for Security</a></li><li>[OE] <a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">Recommendation checklist for Operational Excellence</a></li><li>[PE] <a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">Recommendation checklist for Performance Efficiency</a></li><li>[XO] <a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">Design review checklist for Experience Optimization</a></li></ul><h2 id="the-enumeration-—-49-items-across-the-five-pillars" tabindex="-1">The enumeration — 49 items across the five pillars <a class="header-anchor" href="#the-enumeration-—-49-items-across-the-five-pillars" aria-label="Permalink to &quot;The enumeration — 49 items across the five pillars&quot;">​</a></h2><h3 id="reliability-ppwaf-re-—-8-items" tabindex="-1">Reliability (PPWAF-RE) — 8 items <a class="header-anchor" href="#reliability-ppwaf-re-—-8-items" aria-label="Permalink to &quot;Reliability (PPWAF-RE) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Microsoft code</th><th>Item (Scout paraphrase)</th><th>Scout</th></tr></thead><tbody><tr><td>PPWAF-RE-01</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/simplify" target="_blank" rel="noreferrer">RE:01</a></td><td>The workload design is aligned to business objectives and kept free of unnecessary complexity</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-RE-02</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/identify-flows" target="_blank" rel="noreferrer">RE:02</a></td><td>User and system flows are identified and rated by criticality</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-RE-03</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/failure-mode-analysis" target="_blank" rel="noreferrer">RE:03</a></td><td>Failure mode analysis has been performed on the solution components</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-RE-04</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/metrics" target="_blank" rel="noreferrer">RE:04</a></td><td>Reliability and recovery targets are defined for components, flows and the solution, and a health model describes healthy, degraded and unhealthy states</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-RE-05</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/handle-transient-faults" target="_blank" rel="noreferrer">RE:05</a></td><td>Error handling and transient fault handling are built into apps, flows and integrations</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-RE-06</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/testing-strategy" target="_blank" rel="noreferrer">RE:06</a></td><td>Resiliency and availability scenarios are tested, including simulated malfunction and load</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-RE-07</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/disaster-recovery" target="_blank" rel="noreferrer">RE:07</a></td><td>Business continuity and disaster recovery plans are structured, documented, tested and aligned to the recovery targets</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-RE-08</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/monitoring-alerting-strategy" target="_blank" rel="noreferrer">RE:08</a></td><td>The workload&#39;s health indicators are measured and published</td><td>Manual — questionnaire</td></tr></tbody></table><h3 id="security-ppwaf-se-—-10-items" tabindex="-1">Security (PPWAF-SE) — 10 items <a class="header-anchor" href="#security-ppwaf-se-—-10-items" aria-label="Permalink to &quot;Security (PPWAF-SE) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Microsoft code</th><th>Item (Scout paraphrase)</th><th>Scout</th></tr></thead><tbody><tr><td>PPWAF-SE-01</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/establish-baseline" target="_blank" rel="noreferrer">SE:01</a></td><td>A security baseline aligned to compliance requirements, industry standards and platform recommendations is established and regularly measured against</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-02</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/secure-development-lifecycle" target="_blank" rel="noreferrer">SE:02</a></td><td>A secure development lifecycle with a hardened, mostly automated and auditable supply chain is maintained, and threat modelling informs design</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-03</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/data-classification" target="_blank" rel="noreferrer">SE:03</a></td><td>Sensitivity and information-type labels are applied to workload data and to the systems that process it</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-04</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/segmentation" target="_blank" rel="noreferrer">SE:04</a></td><td>Intentional segmentation and perimeters exist across environments, roles and responsibilities, workload identities and resource organisation</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-05</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/identity-access" target="_blank" rel="noreferrer">SE:05</a></td><td>Identity and access management is strict, conditional and auditable for all users, team members and system components</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-06</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/encryption" target="_blank" rel="noreferrer">SE:06</a></td><td>Data is encrypted with modern industry-standard methods, with scope aligned to data classification and platform-native methods preferred</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-07</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/application-secrets" target="_blank" rel="noreferrer">SE:07</a></td><td>Application secrets are stored hardened, access is restricted and audited, and rotation is regular and can be done in an emergency</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-08</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/monitor-threats" target="_blank" rel="noreferrer">SE:08</a></td><td>A holistic monitoring strategy with modern threat detection alerts reliably into existing security operations processes</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-09</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/testing" target="_blank" rel="noreferrer">SE:09</a></td><td>A comprehensive security testing regimen prevents issues, validates threat prevention and tests threat detection</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-SE-10</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/incident-response" target="_blank" rel="noreferrer">SE:10</a></td><td>Incident response procedures are defined and tested, covering localized issues through disaster recovery, with clear owners</td><td>Manual — questionnaire</td></tr></tbody></table><h3 id="operational-excellence-ppwaf-oe-—-11-items" tabindex="-1">Operational Excellence (PPWAF-OE) — 11 items <a class="header-anchor" href="#operational-excellence-ppwaf-oe-—-11-items" aria-label="Permalink to &quot;Operational Excellence (PPWAF-OE) — 11 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Microsoft code</th><th>Item (Scout paraphrase)</th><th>Scout</th></tr></thead><tbody><tr><td>PPWAF-OE-01</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/fusion-culture" target="_blank" rel="noreferrer">OE:01</a></td><td>Team specialisations are integrated into a fusion practice with clear decision making, responsibilities, continuous improvement and a blameless culture</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-02</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/formalize-operations-tasks" target="_blank" rel="noreferrer">OE:02</a></td><td>Routine, as-needed and emergency operational tasks are formalised through documentation, checklists or automation</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-03</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/formalize-development-practices" target="_blank" rel="noreferrer">OE:03</a></td><td>Ideation and planning follow a formal process with a common prioritised backlog and sufficiently detailed specifications</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-04</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/tools-processes" target="_blank" rel="noreferrer">OE:04</a></td><td>Development and quality assurance practices are optimised and standardised across tooling, source control, design patterns, documentation and style guides</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-05</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/workload-supply-chain" target="_blank" rel="noreferrer">OE:05</a></td><td>A workload supply chain drives changes through predictable, automated pipelines that test and promote across environments</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-06</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/observability" target="_blank" rel="noreferrer">OE:06</a></td><td>A monitoring system captures and exposes operational telemetry, metrics and logs to validate design choices</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-07</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/emergency-response" target="_blank" rel="noreferrer">OE:07</a></td><td>An emergency operations practice exists with health signals, actionable alerts and defined human responsibilities including on-call, incident management, emergency access and postmortems</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-08</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/automate-tasks" target="_blank" rel="noreferrer">OE:08</a></td><td>Procedural tasks that do not benefit from human judgement are automated, preferring off-the-shelf automation, and automation is treated as a workload component</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-09</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/enable-automation" target="_blank" rel="noreferrer">OE:09</a></td><td>Automation for lifecycle, governance and compliance guardrails is designed up front using platform features, not retrofitted</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-10</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/safe-deployments" target="_blank" rel="noreferrer">OE:10</a></td><td>Safe deployment practices are defined: small, incremental, quality-gated releases that cover routine and emergency (hotfix) deployments</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-OE-11</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/mitigation-strategy" target="_blank" rel="noreferrer">OE:11</a></td><td>A deployment failure mitigation strategy provides rapid recovery through rollback, feature disablement or native deployment-pattern capabilities</td><td>Manual — questionnaire</td></tr></tbody></table><h3 id="performance-efficiency-ppwaf-pe-—-10-items" tabindex="-1">Performance Efficiency (PPWAF-PE) — 10 items <a class="header-anchor" href="#performance-efficiency-ppwaf-pe-—-10-items" aria-label="Permalink to &quot;Performance Efficiency (PPWAF-PE) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Microsoft code</th><th>Item (Scout paraphrase)</th><th>Scout</th></tr></thead><tbody><tr><td>PPWAF-PE-01</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/performance-targets" target="_blank" rel="noreferrer">PE:01</a></td><td>Numerical performance targets tied to workload requirements are defined for all workload flows</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-02</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/performance-planning" target="_blank" rel="noreferrer">PE:02</a></td><td>Performance planning is done ahead of predicted changes in usage such as seasonal peaks, product updates, campaigns, events or regulatory changes</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-03</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/select-services" target="_blank" rel="noreferrer">PE:03</a></td><td>Services and product features are selected to meet performance targets and expected capacity changes, weighing platform features against custom builds</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-04</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/collect-performance-data" target="_blank" rel="noreferrer">PE:04</a></td><td>Automatic, continuous and meaningful performance metrics and logs are collected at application, platform, data and operating system levels</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-05</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/performance-test" target="_blank" rel="noreferrer">PE:05</a></td><td>Performance is tested regularly in an environment that matches production and compared with targets and benchmarks</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-06</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/optimize-code" target="_blank" rel="noreferrer">PE:06</a></td><td>Logic is performant and offloads responsibilities to the platform, used only when necessary and for its intended purpose</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-07</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/prioritize-critical-flows" target="_blank" rel="noreferrer">PE:07</a></td><td>The performance of critical flows is prioritised when allocating resources and optimisation effort</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-08</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/optimize-data-performance" target="_blank" rel="noreferrer">PE:08</a></td><td>Data usage is optimised so data stores fit their intended and actual use in the workload</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-09</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/respond-live-performance-issues" target="_blank" rel="noreferrer">PE:09</a></td><td>A plan for live performance issues gives clear communication lines and responsibilities, captures lessons and returns to normal faster next time</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-PE-10</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/continuous-performance-optimize" target="_blank" rel="noreferrer">PE:10</a></td><td>Performance is optimised continuously, focusing on components whose performance deteriorates over time such as databases and networking</td><td>Manual — questionnaire</td></tr></tbody></table><h3 id="experience-optimization-ppwaf-xo-—-10-items" tabindex="-1">Experience Optimization (PPWAF-XO) — 10 items <a class="header-anchor" href="#experience-optimization-ppwaf-xo-—-10-items" aria-label="Permalink to &quot;Experience Optimization (PPWAF-XO) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Microsoft code</th><th>Item (Scout paraphrase)</th><th>Scout</th></tr></thead><tbody><tr><td>PPWAF-XO-01</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/user-centered-design" target="_blank" rel="noreferrer">XO:01</a></td><td>The workload is designed to meet users&#39; expectations and requirements and provides a positive, useful experience</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-02</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/design-standards" target="_blank" rel="noreferrer">XO:02</a></td><td>Established standards, conventions, guidelines and common design patterns are followed, with consistent design elements, terminology and interactions</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-03</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/information-architecture" target="_blank" rel="noreferrer">XO:03</a></td><td>A consistent information architecture is implemented, with consistent navigation, contextual clues, visual indicators and user-friendly labels</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-04</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/usability" target="_blank" rel="noreferrer">XO:04</a></td><td>Ease of use is prioritised, minimising user effort, maximising task efficiency and streamlining complex processes</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-05</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/feedback-guidance" target="_blank" rel="noreferrer">XO:05</a></td><td>Notifications and messages give meaningful, useful and simple guidance, feedback on actions and next steps</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-06</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/layout" target="_blank" rel="noreferrer">XO:06</a></td><td>Layouts are optimised for different contexts and devices and remain usable across screen sizes and resolutions</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-07</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/visual-design" target="_blank" rel="noreferrer">XO:07</a></td><td>User perception and aesthetics are optimised with visually appealing, engaging experiences</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-08</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/interaction-design" target="_blank" rel="noreferrer">XO:08</a></td><td>Interaction design best practices help users complete tasks and keep context</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-09</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/user-interface-content" target="_blank" rel="noreferrer">XO:09</a></td><td>Interface content is task-focused, professional in tone and gives clear direction</td><td>Manual — questionnaire</td></tr><tr><td>PPWAF-XO-10</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/conversation-design" target="_blank" rel="noreferrer">XO:10</a></td><td>Conversations are designed around users&#39; needs and the AI&#39;s objectives, with clear capabilities, natural interactions and fallback mechanisms</td><td>Manual — questionnaire</td></tr></tbody></table><p>XO:10 applies only to workloads with conversational AI; answer N/A otherwise and it is left out of the score.</p><h2 id="what-an-automated-version-would-need" tabindex="-1">What an automated version would need <a class="header-anchor" href="#what-an-automated-version-would-need" aria-label="Permalink to &quot;What an automated version would need&quot;">​</a></h2><p>Authentication is a different permission surface from the Azure Resource Manager Reader role every other Scout rule reads through: the Power Platform API takes a token for <code>https://api.powerplatform.com/.default</code> issued to a Microsoft Entra app registration, and the admin PowerShell module signs in as a Power Platform administrator. An automated version would therefore be opt-in, like <code>-IncludeDevOps</code>, and every rule reading it would be gated so &quot;switch off&quot; or &quot;no access&quot; reads Not assessed rather than &quot;nothing is configured&quot;.</p><p>These are the sources that would answer the most items, with the names as they appear on Microsoft Learn today. A source is only useful where it can show a setting or an inventory. Items about team practice (OE-01, OE-03, SE-02, XO-01 to XO-09 and most of PE) will stay questionnaire items whatever is collected.</p><table tabindex="0"><thead><tr><th>Source</th><th>What it would show</th><th>Items it would answer or inform</th></tr></thead><tbody><tr><td>Power Platform API, <code>EnvironmentManagement</code> namespace (<code>EnvironmentManagement.Environments.Read</code>, <code>.Groups.Read</code>, <code>.Settings.Read</code>; REST <code>https://api.powerplatform.com/environmentmanagement/...</code>)</td><td>Environments with type, region and group membership; environment groups; environment management settings; managed-governance state; backups; business continuity (failover) state</td><td>SE-04 (segmentation), OE-05 and OE-10 (separate stages), RE-07 (backup and disaster recovery state), SE-01 (settings against a baseline)</td></tr><tr><td>Power Platform API, <code>Governance</code> namespace (rule-based policies, environment group rule assignments)</td><td>Governance rules applied to environment groups</td><td>SE-01, OE-09 (guardrails planned up front)</td></tr><tr><td>Power Platform API, <code>Security</code> namespace (<code>Security.Recommendations.Read</code>) and the admin centre Security overview score</td><td>Tenant security recommendations and score</td><td>SE-01, SE-08</td></tr><tr><td>Power Platform API, <code>Analytics</code> namespace (<code>Analytics.AdvisorRecommendations.Read</code>) and the Power Platform for Admins V2 connector (<code>Get Recommendations</code>)</td><td>Admin centre recommended actions</td><td>OE-06, PE-10, RE-08</td></tr><tr><td>Admin PowerShell module <code>Microsoft.PowerApps.Administration.PowerShell</code>: <code>Get-DlpPolicy</code>, <code>Get-AdminDlpPolicy</code></td><td>Data policies, connector classification and scope</td><td>SE-04, SE-05, SE-07 (connectors that carry credentials)</td></tr><tr><td>Admin PowerShell <code>Get-TenantSettings</code>, <code>Get-AdminPowerAppEnvironment</code> (managed-environment <code>governanceConfiguration</code>)</td><td>Tenant settings; whether each environment is managed</td><td>SE-01, SE-04, OE-09</td></tr><tr><td>Power Platform API, <code>PowerApps.Apps.Read</code> and <code>PowerAutomate.Flows.Read</code>; <code>Authorization.RoleAssignments.Read</code></td><td>Inventory of apps and flows with owners; Power Platform role assignments</td><td>SE-05, OE-02, OE-08, RE-02 (what flows exist to be rated)</td></tr><tr><td>Dataverse Web API, per environment: <code>solution</code>, <code>environmentvariabledefinition</code> and <code>connectionreference</code> tables (the <code>ismanaged</code> column shows managed or unmanaged)</td><td>Whether assets sit in solutions, managed versus unmanaged, use of environment variables and connection references</td><td>OE-04, OE-05, OE-10</td></tr><tr><td>Microsoft Purview audit log (Power Platform activity logging)</td><td>Admin and maker activity, connector events, data policy events</td><td>SE-08, OE-06, OE-07</td></tr><tr><td>Microsoft Graph: Entra Conditional Access policies (already read by Scout&#39;s Entra inventory, not yet in <code>collect.json</code>)</td><td>Whether Power Platform sign-in is covered by conditional access and MFA</td><td>SE-05</td></tr><tr><td>Azure Resource Graph (Scout already reads this)</td><td>Application Insights components and Log Analytics workspaces that Power Platform could be exporting to; they are visible, but nothing links them to a Power Platform environment without the admin API</td><td>RE-08, OE-06, PE-04</td></tr></tbody></table><p>The Power Platform API reference states that the management plane is being brought to parity with the admin centre and that new features will be API-first. Some of these APIs are marked preview on Learn today, so each would need its current status confirmed before a rule relied on it.</p>',28)])])}const f=t(n,[["render",i]]);export{p as __pageData,f as default};
